  if (scenario === "rebound") {
    return {
      top1: HEADLINE.reboundTop1BearerSharePct,
      top3: HEADLINE.reboundTop3BearerSharePct,
      hhi: HEADLINE.reboundResidualHhi,
      label: "Annualized rebound",
    };
