                    name="Resilience %"
                    tick={{ fontSize: 11 }}
                    unit="%"
                    domain={[0, 50]}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Gap $B"
                    tick={{ fontSize: 11 }}
                    unit="B"
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) =>
                      name === "Gap $B"
                        ? fmtBn(Number(v), 0)
                        : fmtPct(Number(v), 1)
                    }
                  />
                  <Scatter data={scatterData} name="Regions">
                    {scatterData.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Needs / flows / gap ledgers"
            subtitle="Absolute dollar stack ??? flows remain thin vs AGR needs mid"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={scarcityBars}
                  layout="vertical"
                  margin={{ left: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={96}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => fmtBn(Number(v), 1)} />
                  <Bar dataKey="bn" name="$B" radius={[0, 4, 4, 0]}>
                    {scarcityBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">
        {SOURCES.map((s) => (
          <li key={s.url}>
            <a
              href={s.url}
              className="underline decoration-slate-300 underline-offset-2 hover:text-slate-700"
              target={s.url.startsWith("http") ? "_blank" : undefined}
              rel={s.url.startsWith("http") ? "noreferrer" : undefined}
            >
              {s.label}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

