                  </Pie>
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-2 flex flex-wrap justify-center gap-3 text-xs text-slate-600">
              {INSTRUMENT_MIX.map((s) => (
                <li key={s.id} className="flex items-center gap-1.5">
                  <span
                    className="inline-block h-2.5 w-2.5 rounded-sm"
                    style={{ background: s.fill }}
                  />
                  {s.label} ({fmtPct(s.sharePct)})
                </li>
              ))}
            </ul>
          </ChartCard>

          <ChartCard
            title="OECD adaptation donor tip"
            subtitle={`Estimated shares of ${fmtBn(HEADLINE.oecdAdapt2024Bn)} ??? Top-3 = ${fmtPct(HEADLINE.top3DonorSharePct)}`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={donorBars}
                  layout="vertical"
                  margin={{ left: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    domain={[0, 35]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => fmtPct(Number(v))} />
                  <Bar dataKey="sharePct" name="Share" radius={[0, 4, 4, 0]}>
                    {donorBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "vintage" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Concentration vintage slope"
            subtitle="Research ??? Conc '26 ??? Q3 conc ??? Aug 608 ??? H1 lock holds; rebound is the risk band"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={slopeData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="shortLabel" tick={{ fontSize: 11 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 11 }}
                    domain={
                      slopeMetric === "residualHhi" ? [2400, 3200] : [30, 100]
                    }
                    tickFormatter={(v) =>
                      slopeMetric === "residualHhi"
                        ? fmtHhi(Number(v))
                        : `${v}%`
                    }
                  />
                  {showMdbOnSlope && (
                    <YAxis
                      yAxisId="right"
                      orientation="right"
                      tick={{ fontSize: 11 }}
                      domain={[0, 50]}
                      tickFormatter={(v) => `${v}%`}
                    />
                  )}
                  <Tooltip />
                  <Line
                    yAxisId="left"
                    type="monotone"
                    dataKey={slopeMetric}
                    name={slopeMetric}
                    stroke="#0ea5e9"
                    strokeWidth={2}
                    dot={{ r: 4 }}
                  />
                  {showMdbOnSlope && (
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="mdbTop1Plot"
                      name="MDB Top-1 %"
                      stroke="#f59e0b"
                      strokeWidth={2}
                      strokeDasharray="4 4"
                      dot={{ r: 3 }}
                      connectNulls={false}
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Scenario HHI compare"
            subtitle="FY ??? H1 lock ??? rebound ??? Aug asks whether the soft tip is durable"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={SCENARIO_SCOREBOARD}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="shortLabel" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    domain={[2400, 3000]}
                    tickFormatter={(v) => fmtHhi(Number(v))}
                  />
                  <Tooltip formatter={(v) => fmtHhi(Number(v))} />
                  <Bar dataKey="hhi" name="Residual HHI" radius={[4, 4, 0, 0]}>
                    {SCENARIO_SCOREBOARD.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "gaps" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Protection-gap geography"
            subtitle={`$${HEADLINE.protectionGapBn}B stock ??? Top-3 regions ${fmtPct(HEADLINE.top3GapRegionSharePct, 1)}`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={regionBars}
                  layout="vertical"
                  margin={{ left: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) =>
                      gapMetric === "gapBn" ? `$${v}B` : `${v}%`
                    }
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={88}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) =>
                      gapMetric === "gapBn"
                        ? fmtBn(Number(v), 0)
                        : fmtPct(Number(v), 1)
                    }
                  />
                  <Bar dataKey="value" name="Value" radius={[0, 4, 4, 0]}>
                    {regionBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Resilience ?? gap dollars"
            subtitle="Low-resilience regions still carry large absolute gap stock"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ left: 8, right: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Resilience %"
                    tick={{ fontSize: 11 }}
                    unit="%"
                    domain={[0, 50]}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Gap $B"
                    tick={{ fontSize: 11 }}
                    unit="B"
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) =>
                      name === "Gap $B"
                        ? fmtBn(Number(v), 0)
                        : fmtPct(Number(v), 1)
                    }
                  />
                  <Scatter data={scatterData} name="Regions">
                    {scatterData.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Needs / flows / gap ledgers"
            subtitle="Absolute dollar stack ??? flows remain thin vs AGR needs mid"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={scarcityBars}
                  layout="vertical"
                  margin={{ left: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={96}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip formatter={(v) => fmtBn(Number(v), 1)} />
                  <Bar dataKey="bn" name="$B" radius={[0, 4, 4, 0]}>
                    {scarcityBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <ul className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">
        {SOURCES.map((s) => (
          <li key={s.url}>
            <a
              href={s.url}
              className="underline decoration-slate-300 underline-offset-2 hover:text-slate-700"
              target={s.url.startsWith("http") ? "_blank" : undefined}
              rel={s.url.startsWith("http") ? "noreferrer" : undefined}
            >
              {s.label}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}

